import{z as s,x as A,o as l,c as p,q as r,j as n,D as e,d as t,s as o,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"图形倒塌","description":"","frontmatter":{"title":"图形倒塌","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pattern-collapse.md","filePath":"litho/pattern-collapse.md","lastUpdated":1791413859000}'),d={name:"litho/pattern-collapse.md"};function m(C,a,D,h,u,c){const i=A("Mermaid");return l(),p("div",null,[a[2]||(a[2]=r('<h1 id="图形倒塌" tabindex="-1">图形倒塌 <a class="header-anchor" href="#图形倒塌" aria-label="Permalink to &quot;图形倒塌&quot;">​</a></h1><div class="epigraph"><p>显影后的线在漂洗干燥时被毛细力一对一对拉倒：浮雕已经合格，力学还没有；侧壁再斜，力矩更大。</p><footer>—— 据 Mack 与 Levinson 对 pattern collapse 与显影后毛细力的论述整理</footer></div><p><a href="/litho/sidewall-angle">上一课</a>把剖面角钉成锥或倒锥，并指出刻蚀看见的是斜面。缺口是：角还没交给等离子体之前，漂洗液的表面张力已经可能把相邻线拉塌。本课钉图形倒塌。金属氧化物胶与 CAR 的分叉，留给<a href="/litho/euv-resist">下一课</a>，不在这里换化学家族。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>侧壁角解释的是几何。倒塌解释的是显影–漂洗–干燥这段湿法：线之间的缝里留下液体，弯月面的毛细压差把两根线往一起拉。力随表面张力 \\(\\gamma\\)、接触角和缝宽变，力臂随胶高 \\(H\\) 变。高深宽比 \\(H/W\\) 一旦越过材料能承受的弯矩，线就并、断或贴到衬底。顶视 CD 在倒塌前可以完全在规格里。</p><p>把所有桥连写成光学 OPE 或剂量过了，会漏掉干燥这一步。把倒塌写成「胶太软」而不报深宽比与缝宽，又会漏掉几何。上一课的倒锥（倒八字）让根更细，同样毛细力下更容易折——角是力学前置，不是另一堂光学课。</p><p><span class="marginnote">深宽比就是「线的高 ÷ 线的宽」：一条 100 nm 宽、300 nm 高的线深宽比为 3，像一根身高三倍的细竹竿立在桌上。漂洗水退出时的侧向力对这种细高个格外致命——越细越高，越容易倒。</span></p><h3 id="倒塌发生在液膜离开的时候" tabindex="-1">倒塌发生在液膜离开的时候 <a class="header-anchor" href="#倒塌发生在液膜离开的时候" aria-label="Permalink to &quot;倒塌发生在液膜离开的时候&quot;">​</a></h3><p>曝光、PEB、显影溶蚀可以结束得很好。事故点常是漂洗水（或溶剂）从缝里退出：最后弯月面扫过线高。超临界干燥、表面活性剂漂洗、换低表面张力液体，改的都是这一步，不改空中像。</p><p><span class="marginnote">计量上倒塌像桥连或局部 CD 爆炸。要与真光学桥连拆开：看它是否成对出现、是否沿干燥气流方向有指纹、降低胶厚或加表面活性剂是否立刻消失。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程杠杆分三组。几何：减胶厚、加硬掩模把深宽比预算交给下面的膜、放宽最窄缝。力学：提高膜模量（交联、负胶、金属骨架）、避免倒锥、改善黏附。毛细：降 \\(\\gamma\\)、改接触角、控制干燥速率。Mack 与 Levinson 都把倒塌放进抗蚀剂工艺窗，而不是放进镜头 NA。</p><p>量测：专门的倒塌剂量/焦点矩阵——窗的一边往往不是 CD 出规格，而是成片贴线。报告深宽比、缝宽、漂洗配方，否则「某胶抗塌」不可比。</p><p><span class="marginnote">量倒塌窗时不报深宽比、缝宽与漂洗配方，「这胶抗塌」就是无法比较的空话：换膜堆或换漂洗液，临界值全变。倒塌窗与 CD 窗一样是工艺指纹，必须连条件一起归档，否则下一次复现只能靠猜。</span></p><h3 id="与-cdu-的关系" tabindex="-1">与 CDU 的关系 <a class="header-anchor" href="#与-cdu-的关系" aria-label="Permalink to &quot;与 CDU 的关系&quot;">​</a></h3><p>倒塌是灾难性失效，不进普通 CDU 的 \\(3\\sigma\\)。但临界缝宽附近，未完全倒塌的线已经弯，CD 均值会偏，像一截虚假的疏密偏差。分析要看剖面和成对弯曲，不要只调剂量。</p>',16)),(l(),n(B,null,{default:e(()=>[o(i,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E6%98%BE%E5%BD%B1%E6%B5%AE%E9%9B%95%22%5D%20--%3E%20RINSE%5B%22%E6%BC%82%E6%B4%97%E6%B6%B2%E5%9C%A8%E7%BC%9D%E4%B8%AD%22%5D%0A%20%20RINSE%20--%3E%20CAP%5B%22%E6%AF%9B%E7%BB%86%E5%8A%9B%22%5D%0A%20%20SWA%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E4%BE%A7%E5%A3%81%E8%A7%92%22%5D%20--%3E%20MECH%5B%22%E6%8A%97%E5%BC%AF%E6%88%AA%E9%9D%A2%22%5D%0A%20%20CAP%20--%3E%20MECH%0A%20%20MECH%20--%3E%20COL%5B%22%E5%80%92%E5%A1%8C%20%2F%20%E6%88%90%E5%AF%B9%E5%BC%AF%E6%9B%B2%22%5D%0A%20%20COL%20--%3E%20FIX%5B%22%E5%87%8F%E5%8E%9A%20%2F%20%E9%99%8D%20%CE%B3%20%2F%20%E7%A1%AC%E6%8E%A9%E6%A8%A1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"两根线夹一缝，液体接触线形成弯月面，压差量级 \\(\\sim\\gamma\\cos\\theta/S\\)（\\(S\\) 为缝宽）。压力作用在侧壁上，等效横向力随高度积分。线像悬臂或两端约束的梁，最大应力在根部——倒锥把根削细，应力集中。干燥方向若不对称，成对线会往同一侧倒，缺陷图出现方向性。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"代入数字感受压差：水的表面张力约 0.072 N/m，缝宽 100 nm 时弯月面压差量级约 \\(7\\times10^5\\) Pa，约合七个大气压。这么大的力作用在高几百纳米的细线上，「干燥」并不是一个温柔的动作。")],-1)),a[6]||(a[6]=E("p",null,"EUV 薄胶减轻深宽比，却把黏附和底层抬上来：根若在界面脱黏，塌的是整根拔起。后课金属氧化物胶用更高模量和更薄膜换抗塌，付的是沾污与涂布缺陷。本课先把毛细力学钉住，换胶只是换模量与厚度工作点。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"表面活性剂漂洗会改接触角和残留，也可能改 CD。抗塌工艺必须重新标定阈值模型，不能假设空中像没变所以 OPC 不用动。")],-1)),(l(),n(B,null,{default:e(()=>[o(i,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20MEN%5B%22%E5%BC%AF%E6%9C%88%E9%9D%A2%E5%8E%8B%E5%B7%AE%20~%20%CE%B3cos%CE%B8%2FS%22%5D%20--%3E%20F%5B%22%E4%BE%A7%E5%90%91%E5%8A%9B%E6%B2%BF%E8%83%B6%E9%AB%98%E7%A7%AF%E5%88%86%22%5D%0A%20%20F%20--%3E%20MOM%5B%22%E6%A0%B9%E9%83%A8%E5%BC%AF%E7%9F%A9%20%3D%20%E5%8A%9B%20%C3%97%20%E5%8A%9B%E8%87%82(%E2%89%88%E8%83%B6%E9%AB%98)%22%5D%0A%20%20SWA%5B%22%E5%80%92%E9%94%A5%3A%20%E6%A0%B9%E6%9B%B4%E7%BB%86%22%5D%20--%3E%20SEC%5B%22%E6%8A%97%E5%BC%AF%E6%88%AA%E9%9D%A2%E6%9B%B4%E5%B0%8F%22%5D%0A%20%20SEC%20--%3E%20STRESS%5B%22%E6%A0%B9%E9%83%A8%E5%BA%94%E5%8A%9B%E9%9B%86%E4%B8%AD%22%5D%0A%20%20MOM%20--%3E%20STRESS%0A%20%20STRESS%20--%3E%20Q%7B%22%E8%B6%85%E8%BF%87%E6%9D%90%E6%96%99%E6%89%BF%E5%8F%97%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20COL%5B%22%E5%B9%B6%E7%BA%BF%20%2F%20%E6%96%AD%E8%A3%82%20%2F%20%E8%B4%B4%E5%BA%95%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20OK%5B%22%E7%BA%BF%E5%AD%98%E6%B4%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写某供应商抗塌漂洗的牌号，不给「安全深宽比 = 3」这类假常数——材料、缝宽、干燥方法一起变。干法刻蚀中的线倒是等离子体与应力的另一类倒塌，对象已是硬掩模或器件膜，不在显影毛细账里。</p><p>下一课换 EUV 记录介质时，抗塌会作为薄胶的动机再出现，但机制仍是本课这条力。不要把金属胶的抗塌写成「没有毛细」。漂洗液一旦换成有机溶剂或加表面活性剂，\\(\\gamma\\) 与接触角一起变，CD 与倒塌窗必须重测，不能假设只改了力学、没改阈值。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>图形倒塌是显影后毛细力拉倒高深宽比浮雕，常在干燥瞬间发生。</li><li>侧壁倒锥削弱根部，是上一课角的力学后果。</li><li>杠杆：减厚、硬掩模、模量、降 \\(\\gamma\\)；不是先拧 NA。</li><li>成对弯曲不要误诊成光学桥连或疏密偏差。</li><li>抗塌漂洗改 \\(\\gamma\\) 也会改 CD，阈值模型要重标定。</li><li>EUV 薄胶减轻深宽比，根部脱黏仍是毛细力，不是「没有倒塌」。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>；Levinson, <em>Principles of Lithography</em>。</li></ul>',5))])}const S=s(d,[["render",m]]);export{f as __pageData,S as default};
